+// ── Backend DTOs ──────────────────────────────────────────────
+
+export interface Thread {
+  id: string;
+  user_id: string;
+  title: string | null;
+  created_at: string;
+  updated_at: string;
+}
+
+export interface ThreadListResponse {
+  threads: Thread[];
+  total: number;
+}
+
+export interface BackendMessage {
