    12→}
    13→
    14→export interface ThreadListResponse {
    15→  threads: Thread[];
    16→  total: number;
    17→}
    18→
    19→export interface BackendMessage {
    20→  role: 'user' | 'assistant' | 'tool';
    21→  content: string;
    22→  message_id?: string;
    23→  tool_call_name?: string;
    24→  tool_call_id?: string;
    25→  event_data?: {
    26→    a2ui?: boolean;
    27→    surfaceId?: string;
    28→    messages?: any[];
    29→    [key: string]: any;
    30→  };
    31→}
    32→
    33→export interface ThreadMessagesResponse {
    34→  thread_id: string;
    35→  messages: BackendMessage[];
    36→}
    37→
    38→// ── A2UI payload extracted from history ───────────────────────
    39→
    40→export interface A2UIHistoryPayload {
    41→  surfaceId: string;
    42→  messages: any[];
    43→}
    44→
    45→// ── Mapping functions ─────────────────────────────────────────
    46→
    47→/**
    48→ * Convert backend messages to ChatMessage[] for the chat panel.
    49→ * Skips tool invocations and tool results (those are handled separately for canvas).
    50→ */
    51→export function mapBackendMessages(messages: BackendMessage[]): ChatMessage[] {
    52→  const result: ChatMessage[] = [];
    53→
    54→  for (const msg of messages) {
    55→    // User messages → chat bubble
    56→    if (msg.role === 'user') {
    57→      result.push({
    58→        id: randomUUID(),
    59→        role: 'user',
    60→        content: msg.content,
    61→        timestamp: new Date(),
    62→        isStreaming: false,
    63→        a2uiPayload: null,
    64→        toolCalls: null,
    65→      });
    66→      continue;
    67→    }
    68→
    69→    // Assistant text responses (no tool_call_name) → chat bubble
    70→    if (msg.role === 'assistant' && !msg.tool_call_name) {
    71→      result.push({
    72→        id: msg.message_id || randomUUID(),
    73→        role: 'assistant',
    74→        content: msg.content,
    75→        timestamp: new Date(),
    76→        isStreaming: false,
    77→        a2uiPayload: null,
    78→        toolCalls: null,
    79→      });
    80→      continue;
    81→    }
    82→
    83→    // Skip: assistant with tool_call_name (tool invocation indicator)
    84→    // Skip: tool results (rendered on canvas via extractA2UIPayloads)
    85→  }
    86→
    87→  return result;
    88→}
    89→
    90→/**
    91→ * Extract A2UI visualization payloads from backend messages.
    92→ * These are replayed through A2UIEventService to rebuild the canvas.
    93→ *
    94→ * The A2UI data lives in `msg.content` as a JSON string:
    95→ *   {"a2ui": true, "surfaceId": "chart-xxx", "messages": [...]}
    96→ * The `event_data` field only contains AG-UI protocol metadata.
    97→ */
    98→export function extractA2UIPayloads(messages: BackendMessage[]): A2UIHistoryPayload[] {
    99→  const payloads: A2UIHistoryPayload[] = [];
   100→
   101→  for (const msg of messages) {
   102→    if (msg.role !== 'tool' || !msg.content) continue;
   103→
   104→    try {
   105→      const parsed = JSON.parse(msg.content);
   106→      if (
   107→        parsed.a2ui === true &&
   108→        parsed.surfaceId &&
   109→        Array.isArray(parsed.messages)
   110→      ) {
   111→        payloads.push({
   112→          surfaceId: parsed.surfaceId,
   113→          messages: parsed.messages,
   114→        });
   115→      }
   116→    } catch {
   117→      // Not JSON or not an A2UI payload — skip
   118→    }
   119→  }
   120→
   121→  return payloads;
   122→}
