   191→    const lastSpace = truncated.lastIndexOf(' ');
   192→    return (lastSpace > 20 ? truncated.substring(0, lastSpace) : truncated) + '...';
   193→  }
   194→
   195→  private persistActiveThread(threadId: string): void {
   196→    try {
   197→      localStorage.setItem(STORAGE_KEY, threadId);
   198→    } catch {
   199→      // localStorage unavailable — ignore
   200→    }
   201→  }
   202→
   203→  private restoreActiveThread(): string | null {
   204→    try {
   205→      return localStorage.getItem(STORAGE_KEY);
   206→    } catch {
   207→      return null;
   208→    }
   209→  }
   210→
   211→  private clearPersistedThread(): void {
   212→    try {
   213→      localStorage.removeItem(STORAGE_KEY);
   214→    } catch {
   215→      // ignore
   216→    }
   217→  }
