   198→
   199→  formatDate(isoString: string): string {
   200→    const date = new Date(isoString);
   201→    const now = new Date();
   202→    const diffMs = now.getTime() - date.getTime();
   203→    const diffMins = Math.floor(diffMs / 60_000);
   204→    const diffHours = Math.floor(diffMs / 3_600_000);
   205→    const diffDays = Math.floor(diffMs / 86_400_000);
   206→
   207→    if (diffMins < 1) return 'Just now';
   208→    if (diffMins < 60) return `${diffMins}m ago`;
   209→    if (diffHours < 24) return `${diffHours}h ago`;
   210→    if (diffDays === 1) return 'Yesterday';
   211→    if (diffDays < 7) return `${diffDays}d ago`;
   212→    return date.toLocaleDateString();
   213→  }
   214→}
