     1→import { Injectable, inject } from '@angular/core';
     2→import { HttpAgent, AgentSubscriber } from '@ag-ui/client';
     3→import { ChatStateService } from './chat-state.service';
     4→import { SharedStateService } from './shared-state.service';
     5→import { A2UIEventService } from './a2ui-event.service';
     6→import { environment } from '../../../environments/environment';
     7→
     8→/**
     9→ * AgUiService
    10→ *
    11→ * Wraps @ag-ui/client HttpAgent and bridges AG-UI events to Angular signals.
    12→ * Orchestrates all agent communication via SSE streaming.
    13→ *
    14→ * CRITICAL SERVICE: All agent interactions flow through here.
    15→ */
    16→@Injectable({
    17→  providedIn: 'root',
    18→})
    19→export class AgUiService {
    20→  private chatState = inject(ChatStateService);
    21→  private sharedState = inject(SharedStateService);
    22→  private a2uiEventService = inject(A2UIEventService);
    23→
    24→  private agent: HttpAgent;
    25→  private streamTimeout: ReturnType<typeof setTimeout> | null = null;
    26→  private readonly STREAM_TIMEOUT_MS = 180_000; // 3 minutes
    27→
    28→  constructor() {
    29→    // Initialize the HttpAgent — threadId is auto-generated by the library (uuid v4)
    30→    this.agent = new HttpAgent({
    31→      url: `${environment.apiUrl}${environment.agentEndpoint}`,
    32→      headers: { 'X-User-Id': environment.userId },
    33→    });
    34→  }
    35→
    36→  /** Current thread ID from the underlying HttpAgent */
    37→  get threadId(): string {
    38→    return this.agent.threadId;
    39→  }
    40→
    41→  /** Switch to an existing thread (destroys current HttpAgent, creates new one) */
    42→  switchThread(threadId: string): void {
    43→    this.clearStreamTimeout();
    44→    this.agent = new HttpAgent({
    45→      url: `${environment.apiUrl}${environment.agentEndpoint}`,
    46→      threadId,
    47→      headers: { 'X-User-Id': environment.userId },
    48→    });
    49→  }
    50→
    51→  /** Start a fresh thread (auto-generates new threadId) */
    52→  startNewThread(): void {
    53→    this.clearStreamTimeout();
    54→    this.agent = new HttpAgent({
    55→      url: `${environment.apiUrl}${environment.agentEndpoint}`,
    56→      headers: { 'X-User-Id': environment.userId },
    57→    });
    58→  }
    59→
    60→  /**
    61→   * Run the agent with current messages and shared state
    62→   * Uses HttpAgent from @ag-ui/client to handle request formatting
    63→   */
    64→  async runAgent(): Promise<void> {
    65→    try {
    66→      // Recreate agent with preserved threadId. Backend uses persisted history,
    67→      // so we only send the latest user message (not full conversation).
    68→      const threadId = this.agent.threadId;
    69→      const latestUserMsg = this.chatState
    70→        .messages()
    71→        .filter((msg) => msg.role === 'user')
    72→        .slice(-1)
    73→        .map((msg) => ({
    74→          id: msg.id,
    75→          role: 'user' as const,
    76→          content: [{ type: 'text' as const, text: msg.content }],
    77→        }));
    78→
    79→      this.agent = new HttpAgent({
    80→        url: `${environment.apiUrl}${environment.agentEndpoint}`,
    81→        threadId,
    82→        headers: { 'X-User-Id': environment.userId },
    83→        initialMessages: latestUserMsg,
    84→        initialState: this.sharedState.agentContext(),
    85→      });
    86→
    87→      // Start streaming
    88→      this.chatState.isStreaming.set(true);
    89→
    90→      // Set stream timeout to prevent infinite hangs
    91→      this.streamTimeout = setTimeout(() => {
    92→        console.warn(`Agent stream timeout after ${this.STREAM_TIMEOUT_MS / 1000}s, aborting`);
    93→        this.cancel();
    94→        this.chatState.setError('Agent response timed out — please try again');
    95→      }, this.STREAM_TIMEOUT_MS);
    96→
    97→      // Run agent with typed subscriber callbacks
    98→      await this.agent.runAgent(
    99→        {
   100→          tools: [],
   101→          context: [],
   102→          forwardedProps: {},
   103→        },
   104→        this.buildSubscriber(),
   105→      );
   106→    } catch (error: any) {
   107→      this.clearStreamTimeout();
   108→      // Suppress noisy AGUIError when library sends RUN_FINISHED after RUN_ERROR
   109→      const msg = error?.message || '';
   110→      if (msg.includes('The run has already errored')) {
   111→        return;
   112→      }
   113→      console.error('Agent error:', error);
   114→      this.chatState.setError(msg || 'Failed to connect to agent');
   115→      this.chatState.isStreaming.set(false);
   116→    }
   117→  }
   118→
   119→  /**
   120→   * Clear the stream timeout if active
   121→   */
   122→  private clearStreamTimeout(): void {
   123→    if (this.streamTimeout) {
   124→      clearTimeout(this.streamTimeout);
   125→      this.streamTimeout = null;
   126→    }
   127→  }
   128→
   129→  /**
   130→   * Cancel the current agent stream
   131→   */
   132→  cancel(): void {
   133→    this.clearStreamTimeout();
   134→    this.agent.abortRun();
   135→    this.chatState.finalizeStreamingMessage();
   136→    this.chatState.isStreaming.set(false);
   137→  }
   138→
   139→  /**
   140→   * Build a typed AgentSubscriber — replaces the manual switch(event.type).
   141→   * Each callback receives typed event data and accumulated buffers from the library.
   142→   */
   143→  private buildSubscriber(): AgentSubscriber {
   144→    return {
   145→      // ── Logging (fires for every event) ────────────────────────
   146→      onEvent: ({ event }) => {
   147→        console.log('AG-UI Event:', event.type, event);
   148→      },
   149→
   150→      // ── Lifecycle ─────────────────────────────────────────────
   151→      onRunStartedEvent: () => {
   152→        this.chatState.isStreaming.set(true);
   153→      },
   154→
   155→      onRunFinishedEvent: () => {
   156→        this.chatState.isStreaming.set(false);
   157→      },
   158→
   159→      onRunErrorEvent: ({ event }) => {
   160→        // Suppress user-initiated abort — not an actual error
   161→        if (('code' in event && (event as any).code === 'abort') ||
   162→            ('message' in event && String((event as any).message).includes('aborted'))) {
   163→          return;
   164→        }
   165→        if (this.chatState.currentStreamingMessage()) {
   166→          this.chatState.finalizeStreamingMessage();
   167→        }
   168→        const errorMessage = (event as any).error ?? 'Agent error';
   169→        this.chatState.setError(typeof errorMessage === 'string' ? errorMessage : 'Agent error');
   170→        this.chatState.isStreaming.set(false);
   171→      },
   172→
   173→      onRunFailed: ({ error }) => {
   174→        this.clearStreamTimeout();
   175→        const msg = error?.message || '';
   176→        if (msg.includes('The run has already errored') || msg.includes('aborted')) {
   177→          return;
   178→        }
   179→        console.error('Agent error:', error);
   180→        this.chatState.setError(msg || 'Failed to connect to agent');
   181→        this.chatState.isStreaming.set(false);
   182→      },
   183→
   184→      onRunFinalized: () => {
   185→        this.clearStreamTimeout();
   186→        this.chatState.finalizeStreamingMessage();
   187→        this.chatState.isStreaming.set(false);
   188→      },
   189→
   190→      // ── Text message streaming ────────────────────────────────
   191→      onTextMessageStartEvent: () => {
   192→        this.chatState.startAssistantMessage();
   193→      },
   194→
   195→      onTextMessageContentEvent: ({ event }) => {
   196→        this.chatState.appendStreamingContent(event.delta);
   197→      },
   198→
   199→      onTextMessageEndEvent: ({ textMessageBuffer }) => {
   200→        // Check if the completed message is raw chart JSON (not meant for display).
   201→        const streamingMsg = this.chatState.currentStreamingMessage();
   202→        if (streamingMsg && this.isChartJsonContent(textMessageBuffer)) {
   203→          this.chatState.removeMessage(streamingMsg.id);
   204→          this.chatState.currentStreamingMessage.set(null);
   205→          this.chatState.isStreaming.set(false);
   206→        } else {
   207→          this.chatState.finalizeStreamingMessage();
   208→        }
   209→      },
   210→
   211→      // ── Tool calls ────────────────────────────────────────────
   212→      onToolCallStartEvent: ({ event }) => {
   213→        this.chatState.addToolCall({
   214→          toolName: event.toolCallName,
   215→          status: 'running',
   216→        });
   217→      },
   218→
   219→      onToolCallArgsEvent: ({ toolCallName, partialToolCallArgs }) => {
   220→        this.chatState.addToolCall({
   221→          toolName: toolCallName,
   222→          status: 'running',
   223→          arguments: partialToolCallArgs,
   224→        });
   225→      },
   226→
   227→      onToolCallEndEvent: ({ toolCallName }) => {
   228→        this.chatState.addToolCall({
   229→          toolName: toolCallName,
   230→          status: 'complete',
   231→        });
   232→      },
   233→
   234→      onToolCallResultEvent: ({ event }) => {
   235→        // Check for A2UI visualization payload in content
   236→        const content = (event as any).content;
   237→        if (!content) return;
   238→
   239→        try {
   240→          const parsed = typeof content === 'string' ? JSON.parse(content) : content;
   241→          if (parsed?.a2ui === true && parsed.surfaceId && Array.isArray(parsed.messages)) {
   242→            this.a2uiEventService.handleA2UIMessages(parsed.surfaceId, parsed.messages);
   243→          }
   244→        } catch {
   245→          // Not JSON or not A2UI payload — ignore
   246→        }
   247→      },
   248→
   249→      // ── State sync (library auto-applies patches via fast-json-patch) ──
   250→      onStateDeltaEvent: ({ agent }) => {
   251→        this.sharedState.syncFromAgent(agent.state);
   252→      },
   253→
   254→      onStateSnapshotEvent: ({ agent }) => {
   255→        this.sharedState.syncFromAgent(agent.state);
   256→      },
   257→
   258→      // ── Custom events (A2UI surface updates) ──────────────────
   259→      onCustomEvent: ({ event }) => {
   260→        if (event.name === 'a2ui_surface_update') {
   261→          const data = (event as any).data;
   262→          if (data?.surfaceId && Array.isArray(data.messages)) {
   263→            this.a2uiEventService.handleA2UIMessages(data.surfaceId, data.messages);
   264→          }
   265→        }
   266→      },
   267→    };
   268→  }
   269→
   270→  /**
   271→   * Detect if message content is raw chart JSON config (not user-facing text).
   272→   * Handles both pure JSON and content where JSON is wrapped with minor
   273→   * surrounding text or markdown fences.
   274→   */
   275→  private isChartJsonContent(content: string): boolean {
   276→    if (!content || !content.trim()) return false;
   277→
   278→    const jsonCandidate = this.extractJsonObject(content);
   279→    if (!jsonCandidate) return false;
   280→
   281→    try {
   282→      const parsed = JSON.parse(jsonCandidate);
   283→      if (!parsed || typeof parsed !== 'object') return false;
   284→
   285→      // Chart configuration: has chart_type/graphType + data keys
   286→      if (
   287→        ('chart_type' in parsed || 'graphType' in parsed) &&
   288→        ('labels' in parsed || 'datasets' in parsed || 'data' in parsed)
   289→      ) {
   290→        return true;
   291→      }
   292→
   293→      // Chart reference map: all keys match "chart-XXXX" pattern with string values
   294→      const keys = Object.keys(parsed);
   295→      if (
   296→        keys.length > 0 &&
   297→        keys.every((k) => /^chart-/.test(k) && typeof parsed[k] === 'string')
   298→      ) {
   299→        return true;
   300→      }
   301→
   302→      return false;
   303→    } catch {
   304→      return false;
   305→    }
   306→  }
   307→
   308→  /**
   309→   * Extract a JSON object string from content that may have surrounding text.
   310→   * Returns the JSON substring if found, or null.
   311→   */
   312→  private extractJsonObject(content: string): string | null {
   313→    let trimmed = content.trim();
   314→
   315→    // Pure JSON case (most common)
   316→    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
   317→      return trimmed;
   318→    }
   319→
   320→    // Strip markdown code fences: ```json ... ``` or ``` ... ```
   321→    const fenceMatch = trimmed.match(/```(?:json)?\s*(\{[\s\S]*\})\s*```/);
   322→    if (fenceMatch) {
   323→      return fenceMatch[1].trim();
   324→    }
   325→
   326→    // Find the outermost { ... } in the content
   327→    const firstBrace = trimmed.indexOf('{');
   328→    const lastBrace = trimmed.lastIndexOf('}');
   329→    if (firstBrace !== -1 && lastBrace > firstBrace) {
   330→      return trimmed.substring(firstBrace, lastBrace + 1);
   331→    }
   332→
   333→    return null;
   334→  }
   335→}
