   638→+/**
   639→+ * Convert backend messages to ChatMessage[] for the chat panel.
   640→+ * Skips tool invocations and tool results (those are handled separately for canvas).
   641→+ */
   642→+export function mapBackendMessages(messages: BackendMessage[]): ChatMessage[] {
   643→+  const result: ChatMessage[] = [];
   644→+
   645→+  for (const msg of messages) {
   646→+    // User messages → chat bubble
   647→+    if (msg.role === 'user') {
   648→+      result.push({
   649→+        id: randomUUID(),
   650→+        role: 'user',
   651→+        content: msg.content,
   652→+        timestamp: new Date(),
   653→+        isStreaming: false,
   654→+        a2uiPayload: null,
   655→+        toolCalls: null,
   656→+      });
   657→+      continue;
   658→+    }
   659→+
   660→+    // Assistant text responses (no tool_call_name) → chat bubble
   661→+    if (msg.role === 'assistant' && !msg.tool_call_name) {
   662→+      result.push({
   663→+        id: msg.message_id || randomUUID(),
   664→+        role: 'assistant',
   665→+        content: msg.content,
   666→+        timestamp: new Date(),
   667→+        isStreaming: false,
   668→+        a2uiPayload: null,
   669→+        toolCalls: null,
   670→+      });
   671→+      continue;
   672→+    }
   673→+
   674→+    // Skip: assistant with tool_call_name (tool invocation indicator)
   675→+    // Skip: tool results (rendered on canvas via extractA2UIPayloads)
   676→+  }
   677→+
   678→+  return result;
   679→+}
