   681→+/**
   682→+ * Extract A2UI visualization payloads from backend messages.
   683→+ * These are replayed through A2UIEventService to rebuild the canvas.
   684→+ *
   685→+ * The A2UI data lives in `msg.content` as a JSON string:
   686→+ *   {"a2ui": true, "surfaceId": "chart-xxx", "messages": [...]}
   687→+ * The `event_data` field only contains AG-UI protocol metadata.
   688→+ */
   689→+export function extractA2UIPayloads(messages: BackendMessage[]): A2UIHistoryPayload[] {
   690→+  const payloads: A2UIHistoryPayload[] = [];
   691→+
   692→+  for (const msg of messages) {
   693→+    if (msg.role !== 'tool' || !msg.content) continue;
   694→+
   695→+    try {
   696→+      const parsed = JSON.parse(msg.content);
   697→+      if (
   698→+        parsed.a2ui === true &&
   699→+        parsed.surfaceId &&
   700→+        Array.isArray(parsed.messages)
   701→+      ) {
   702→+        payloads.push({
   703→+          surfaceId: parsed.surfaceId,
   704→+          messages: parsed.messages,
   705→+        });
   706→+      }
   707→+    } catch {
   708→+      // Not JSON or not an A2UI payload — skip
   709→+    }
   710→+  }
   711→+
   712→+  return payloads;
   713→+}
