     1→import { Component, ChangeDetectionStrategy } from '@angular/core';
     2→import { CommonModule } from '@angular/common';
     3→import { Renderer } from '@a2ui/angular';
     4→import { CatalogBaseComponent } from '../catalog-base.component';
     5→
     6→/**
     7→ * CompositeDashboardComponent
     8→ *
     9→ * Container for multiple A2UI components in a grid layout.
    10→ * Uses A2UI Renderer directive to render resolved child nodes.
    11→ *
    12→ * CRITICAL: Properties accessed via getProp() from component().properties.
    13→ * After processMessages(), children are fully resolved AnyComponentNode[].
    14→ */
    15→@Component({
    16→  selector: 'app-composite-dashboard',
    17→  standalone: true,
    18→  changeDetection: ChangeDetectionStrategy.OnPush,
    19→  imports: [CommonModule, Renderer],
    20→  template: `
    21→    <div class="w-full p-4">
    22→      <!-- Title -->
    23→      @if (title) {
    24→        <h2 class="text-2xl font-bold text-gray-900 mb-6">{{ title }}</h2>
    25→      }
    26→
    27→      <!-- KPI row: compact horizontal strip -->
    28→      @if (kpiChildren.length) {
    29→        <div class="flex flex-wrap gap-4 mb-6">
    30→          @for (child of kpiChildren; track child.id) {
    31→            <div class="flex-1 min-w-[180px]">
    32→              <ng-container a2ui-renderer [surfaceId]="surfaceId()!" [component]="child" />
    33→            </div>
    34→          }
    35→        </div>
    36→      }
    37→
    38→      <!-- Content grid: charts, tables, insights get more space -->
    39→      @if (contentChildren.length) {
    40→        <div [class]="contentGridClass">
    41→          @for (child of contentChildren; track child.id) {
    42→            <div>
    43→              @if (child.properties?.title) {
    44→                <h3 class="text-base font-semibold text-gray-800 mb-2">{{ child.properties.title }}</h3>
    45→              }
    46→              <ng-container a2ui-renderer [surfaceId]="surfaceId()!" [component]="child" />
    47→            </div>
    48→          }
    49→        </div>
    50→      }
    51→    </div>
    52→  `,
    53→})
    54→export class CompositeDashboardComponent extends CatalogBaseComponent {
    55→  private static readonly KPI_TYPES = new Set(['KPICard', 'RAGIndicator']);
    56→
    57→  get title(): string | undefined {
    58→    return this.getProp<string>('title');
    59→  }
    60→
    61→  get layout(): 'auto' | '2-column' | '3-column' | '1-top-2-bottom' {
    62→    return this.getProp<any>('layout', 'auto')!;
    63→  }
    64→
    65→  private get children(): any[] {
    66→    const raw = this.getProp<any>('children');
    67→    return Array.isArray(raw) ? raw : [];
    68→  }
    69→
    70→  get kpiChildren(): any[] {
    71→    return this.children.filter((c: any) => CompositeDashboardComponent.KPI_TYPES.has(c.type));
    72→  }
    73→
    74→  get contentChildren(): any[] {
    75→    return this.children.filter((c: any) => !CompositeDashboardComponent.KPI_TYPES.has(c.type));
    76→  }
    77→
    78→  protected get contentGridClass(): string {
    79→    const count = this.contentChildren.length;
    80→    if (count === 1) return 'grid grid-cols-1 gap-6';
    81→    return 'grid grid-cols-1 md:grid-cols-2 gap-6';
    82→  }
    83→}
