  2689→+  }
  2690→+
  2691→+  async onSelectThread(thread: Thread): Promise<void> {
  2692→+    // Don't navigate if we're editing this thread's title
  2693→+    if (this.editingThreadId() === thread.id) return;
  2694→+
  2695→+    if (thread.id === this.conversation.activeThreadId()) {
  2696→+      this.close();
  2697→+      return;
  2698→+    }
  2699→+    await this.conversation.switchThread(thread.id);
  2700→+    this.close();
  2701→+  }
  2702→+
  2703→+  startEdit(event: Event, thread: Thread): void {
  2704→+    event.stopPropagation();
  2705→+    this.editingThreadId.set(thread.id);
  2706→+    this.editingTitle.set(thread.title || '');
