  2708→+    setTimeout(() => this.editInputRef?.nativeElement.focus(), 0);
  2709→+  }
  2710→+
  2711→+  async saveTitle(thread: Thread): Promise<void> {
  2712→+    const newTitle = this.editingTitle().trim();
  2713→+    this.editingThreadId.set(null);
  2714→+    if (newTitle && newTitle !== (thread.title || '')) {
  2715→+      await this.conversation.renameThread(thread.id, newTitle);
  2716→+    }
  2717→+  }
  2718→+
  2719→+  cancelEdit(): void {
  2720→+    this.editingThreadId.set(null);
  2721→+  }
  2722→+
  2723→+  async onDeleteThread(event: Event, thread: Thread): Promise<void> {
  2724→+    event.stopPropagation();
