  2728→+  formatDate(isoString: string): string {
  2729→+    const date = new Date(isoString);
  2730→+    const now = new Date();
  2731→+    const diffMs = now.getTime() - date.getTime();
  2732→+    const diffMins = Math.floor(diffMs / 60_000);
  2733→+    const diffHours = Math.floor(diffMs / 3_600_000);
  2734→+    const diffDays = Math.floor(diffMs / 86_400_000);
  2735→+
  2736→+    if (diffMins < 1) return 'Just now';
  2737→+    if (diffMins < 60) return `${diffMins}m ago`;
  2738→+    if (diffHours < 24) return `${diffHours}h ago`;
  2739→+    if (diffDays === 1) return 'Yesterday';
  2740→+    if (diffDays < 7) return `${diffDays}d ago`;
  2741→+    return date.toLocaleDateString();
  2742→+  }
