    81→  protected chatState = inject(ChatStateService);
    82→  private agUiService = inject(AgUiService);
    83→  private conversation = inject(ConversationService);
    84→
    85→  protected inputText = signal<string>('');
    86→  protected isStreaming = this.chatState.isStreaming;
    87→
    88→  protected canSend = computed(() => {
    89→    return this.inputText().trim().length > 0 && !this.isStreaming();
    90→  });
    91→
    92→  /**
    93→   * Handle keyboard events
    94→   */
    95→  protected onKeyDown(event: KeyboardEvent): void {
    96→    if (event.key === 'Enter' && !event.shiftKey) {
    97→      event.preventDefault();
    98→      this.onSend();
    99→    }
   100→  }
   101→
   102→  /**
   103→   * Send message
   104→   */
   105→  protected async onSend(): Promise<void> {
   106→    const text = this.inputText().trim();
   107→    if (!text || this.isStreaming()) return;
   108→
   109→    // Clear input immediately
   110→    this.inputText.set('');
   111→    this.resetTextareaHeight();
   112→
   113→    // Add user message
   114→    this.chatState.addUserMessage(text);
   115→
   116→    // Run agent, then sync thread state (captures threadId, refreshes sidebar)
   117→    try {
   118→      await this.agUiService.runAgent();
   119→      await this.conversation.onRunCompleted();
   120→    } catch (error) {
   121→      console.error('Failed to run agent:', error);
   122→    }
   123→  }
   124→
   125→  /**
   126→   * Cancel current stream
   127→   */
   128→  protected onCancel(): void {
   129→    this.agUiService.cancel();
   130→  }
   131→
   132→  /**
   133→   * Auto-resize textarea based on content
   134→   */
   135→  protected autoResize(): void {
   136→    if (!this.textareaRef) return;
   137→
   138→    const textarea = this.textareaRef.nativeElement;
   139→    textarea.style.height = 'auto';
   140→    textarea.style.height = `${Math.min(textarea.scrollHeight, 96)}px`; // max-h-24 = 96px
   141→  }
   142→
   143→  /**
   144→   * Reset textarea height
   145→   */
   146→  private resetTextareaHeight(): void {
   147→    if (!this.textareaRef) return;
   148→    this.textareaRef.nativeElement.style.height = 'auto';
   149→  }
   150→}
