    41→export class GraphComponent extends CatalogBaseComponent implements AfterViewInit, OnDestroy {
    42→  private static readonly MODERN_PALETTE = ['#6366f1', '#8b5cf6', '#a78bfa', '#c4b5fd', '#818cf8', '#7c3aed'];
    43→
