    46→  private chartInstance: Chart | null = null;
    47→  private viewReady = false;
    48→
    49→  constructor() {
    50→    super();
    51→    // Re-render chart when A2UI properties change (e.g., drill-down updates data)
    52→    effect(() => {
    53→      // Read reactive signals to establish dependency tracking
    54→      const props = this.component().properties;
    55→      // Only re-render if the view is ready (canvas exists)
    56→      if (this.viewReady && props) {
    57→        this.renderChart();
    58→      }
    59→    });
    60→  }
    61→
