    73→  }
    74→
    75→  get xLabel(): string | undefined {
    76→    return this.getProp<string>('xLabel');
    77→  }
    78→
    79→  get yLabel(): string | undefined {
    80→    return this.getProp<string>('yLabel');
    81→  }
    82→
    83→  get valuePrefix(): string {
    84→    return this.getProp<string>('valuePrefix', '')!;
    85→  }
    86→
    87→  get valueSuffix(): string {
    88→    return this.getProp<string>('valueSuffix', '')!;
    89→  }
    90→
    91→  get interactive(): boolean {
    92→    if (!FEATURE_FLAGS.DRILL_DOWN_ENABLED) return false;
    93→    return this.getProp<boolean>('interactive', true)!;
    94→  }
    95→
    96→  get showLegend(): boolean {
