   125→  }
   126→
   127→  get isModernLine(): boolean {
   128→    return FEATURE_FLAGS.MODERN_CHART_STYLE && (this.graphType === 'line' || this.graphType === 'area');
   129→  }
   130→
   131→  get isModernPie(): boolean {
   132→    return FEATURE_FLAGS.MODERN_CHART_STYLE && (this.graphType === 'pie' || this.graphType === 'doughnut');
