   138→
   139→  /**
   140→   * Render or update the chart
   141→   */
   142→  private renderChart(): void {
   143→    if (!this.canvasRef || !this.data || !this.graphType) {
   144→      console.warn('GraphComponent: Missing required data or canvas reference');
   145→      return;
   146→    }
   147→
   148→    // Destroy existing chart before creating new one
   149→    this.destroyChart();
   150→
   151→    const canvas = this.canvasRef.nativeElement;
   152→    const ctx = canvas.getContext('2d');
   153→    if (!ctx) return;
   154→
   155→    // Map A2UI chart type to Chart.js type
   156→    const chartType = this.mapToChartJsType(this.graphType);
   157→
   158→    let config: ChartConfiguration;
   159→    if (this.isModernBar || this.isModernStackedBar) {
   160→      config = this.buildModernBarConfig(chartType, ctx);
   161→    } else if (this.isModernLine) {
   162→      config = this.buildModernLineConfig(chartType, ctx);
   163→    } else if (this.isModernPie) {
   164→      config = this.buildModernPieConfig(chartType);
   165→    } else {
   166→      config = this.buildClassicConfig(chartType);
   167→    }
   168→
