   176→  private buildClassicConfig(chartType: ChartJsType): ChartConfiguration {
   177→    return {
   178→      type: chartType,
   179→      data: {
   180→        labels: this.data!.labels || [],
   181→        datasets: this.data!.datasets.map((dataset, index) => ({
   182→          label: dataset.label,
   183→          data: dataset.data,
   184→          backgroundColor: this.getColors(index, this.data!.datasets.length, 0.6),
   185→          borderColor: this.getColors(index, this.data!.datasets.length, 1),
   186→          borderWidth: 2,
   187→        })),
   188→      },
   189→      options: {
   190→        responsive: true,
   191→        maintainAspectRatio: false,
   192→        plugins: {
   193→          legend: {
   194→            display: this.showLegend,
   195→            position: 'top',
   196→          },
   197→          tooltip: {
   198→            enabled: true,
   199→          },
   200→        },
   201→        scales: this.buildScales(chartType),
   202→        onClick: this.interactive ? (event, elements) => this.handleChartClick(event, elements) : undefined,
   203→      },
   204→    };
   205→  }
   206→
   207→  /**
   208→   * Modern bar chart configuration — refined styling behind MODERN_CHART_STYLE flag
   209→   */
   210→  private buildModernBarConfig(chartType: ChartJsType, ctx: CanvasRenderingContext2D): ChartConfiguration {
   211→    const labels = this.data!.labels || [];
   212→    const isSingleDataset = this.data!.datasets.length === 1;
   213→    const isStacked = this.graphType === 'stackedBar';
   214→    const isHorizontal = this.isHorizontalBar;
   215→    const modernPalette = GraphComponent.MODERN_PALETTE;
   216→
   217→    const formatValue = this.formatCompactValue.bind(this);
   218→
   219→    // Inline plugin: renders data labels next to each bar
   220→    const barDataLabelsPlugin = {
   221→      id: 'barDataLabels',
   222→      afterDatasetsDraw(chart: any) {
   223→        const { ctx: drawCtx } = chart;
   224→        chart.data.datasets.forEach((dataset: any, dsIdx: number) => {
   225→          const meta = chart.getDatasetMeta(dsIdx);
   226→          meta.data.forEach((bar: any, idx: number) => {
   227→            const value = dataset.data[idx];
   228→            if (value == null) return;
   229→            const label = formatValue(value);
   230→            drawCtx.save();
   231→            drawCtx.font = "600 12px 'Inter', sans-serif";
   232→            drawCtx.fillStyle = '#374151';
   233→            if (isHorizontal) {
   234→              // Position label to the right of the bar
   235→              drawCtx.textAlign = 'left';
   236→              drawCtx.textBaseline = 'middle';
   237→              drawCtx.fillText(label, bar.x + 8, bar.y);
   238→            } else {
   239→              // Position label above the bar
   240→              drawCtx.textAlign = 'center';
   241→              drawCtx.textBaseline = 'bottom';
   242→              drawCtx.fillText(label, bar.x, bar.y - 8);
   243→            }
   244→            drawCtx.restore();
   245→          });
   246→        });
   247→      },
   248→    };
   249→
   250→    return {
   251→      type: chartType,
   252→      data: {
   253→        labels,
   254→        datasets: this.data!.datasets.map((dataset, dsIndex) => {
   255→          // Use horizontal or vertical gradient based on orientation
   256→          const createGradient = isHorizontal
   257→            ? (hex: string) => this.createHorizontalBarGradient(ctx, hex)
   258→            : (hex: string) => this.createBarGradient(ctx, hex);
   259→
   260→          // For single dataset: each bar gets a distinct color via array
   261→          // For multi-dataset: each dataset gets one color
   262→          const colors = isSingleDataset
   263→            ? labels.map((_, i) => createGradient(modernPalette[i % modernPalette.length]))
   264→            : createGradient(modernPalette[dsIndex % modernPalette.length]);
   265→
   266→          return {
   267→            label: dataset.label,
   268→            data: dataset.data,
   269→            backgroundColor: colors,
   270→            borderColor: 'transparent',
   271→            borderWidth: 0,
   272→            borderRadius: 6,
   273→            borderSkipped: false as const,
   274→            barPercentage: 0.6,
   275→            categoryPercentage: 0.7,
   276→            hoverBackgroundColor: isSingleDataset
   277→              ? labels.map((_, i) => modernPalette[i % modernPalette.length])
   278→              : modernPalette[dsIndex % modernPalette.length],
   279→          };
   280→        }),
   281→      },
   282→      plugins: [barDataLabelsPlugin],
   283→      options: {
   284→        responsive: true,
   285→        maintainAspectRatio: false,
   286→        indexAxis: isHorizontal ? ('y' as const) : ('x' as const),
   287→        layout: {
   288→          padding: isHorizontal
   289→            ? { top: 8, right: 48, bottom: 8, left: 8 }
   290→            : { top: 28, right: 16, bottom: 8, left: 8 },
   291→        },
   292→        plugins: {
   293→          legend: {
   294→            display: this.showLegend && (!isSingleDataset || isStacked),
   295→            position: 'top',
   296→            labels: {
   297→              usePointStyle: true,
   298→              pointStyle: 'rectRounded',
   299→              padding: 20,
   300→              font: { size: 12, family: "'Inter', sans-serif" },
   301→              color: '#6b7280',
   302→            },
   303→          },
   304→          tooltip: {
   305→            enabled: true,
   306→            backgroundColor: '#1f2937',
   307→            titleColor: '#f9fafb',
   308→            bodyColor: '#e5e7eb',
   309→            titleFont: { size: 13, weight: 'bold' as const, family: "'Inter', sans-serif" },
   310→            bodyFont: { size: 12, family: "'Inter', sans-serif" },
   311→            padding: { top: 10, right: 14, bottom: 10, left: 14 },
   312→            cornerRadius: 8,
   313→            displayColors: false,
   314→            callbacks: {
   315→              label: (tooltipItem: any) => {
   316→                const value = isHorizontal ? tooltipItem.parsed.x : tooltipItem.parsed.y;
   317→                return `${tooltipItem.dataset.label}: ${this.formatCompactValue(value)}`;
   318→              },
   319→            },
   320→          },
   321→        },
   322→        scales: isHorizontal
   323→          ? {
   324→              // Horizontal bar: X is the value axis, Y is the category axis
   325→              x: {
   326→                stacked: isStacked,
   327→                title: { display: false },
   328→                beginAtZero: true,
   329→                grid: { color: '#f3f4f6' },
   330→                border: { display: false },
   331→                ticks: {
   332→                  color: '#9ca3af',
   333→                  font: { size: 11, family: "'Inter', sans-serif" },
   334→                  padding: 8,
   335→                  callback: (tickValue: string | number) => {
   336→                    return this.formatCompactValue(Number(tickValue));
   337→                  },
   338→                },
   339→              },
   340→              y: {
   341→                stacked: isStacked,
   342→                title: { display: false },
   343→                grid: { display: false },
   344→                border: { display: false },
   345→                ticks: {
   346→                  color: '#6b7280',
   347→                  font: { size: 12, family: "'Inter', sans-serif" },
   348→                  padding: 8,
   349→                },
   350→              },
   351→            }
   352→          : {
   353→              x: {
   354→                stacked: isStacked,
   355→                title: { display: false },
   356→                grid: { display: false },
   357→                border: { display: false },
   358→                ticks: {
   359→                  color: '#6b7280',
   360→                  font: { size: 12, family: "'Inter', sans-serif" },
   361→                  padding: 8,
   362→                },
   363→              },
   364→              y: {
   365→                stacked: isStacked,
   366→                title: { display: false },
   367→                beginAtZero: true,
   368→                grid: { color: '#f3f4f6' },
   369→                border: { display: false, dash: [4, 4] },
