   385→  /**
   386→   * Modern line/area configuration — refined styling behind MODERN_CHART_STYLE flag
   387→   */
   388→  private buildModernLineConfig(chartType: ChartJsType, ctx: CanvasRenderingContext2D): ChartConfiguration {
   389→    const modernPalette = GraphComponent.MODERN_PALETTE;
   390→    const isArea = this.graphType === 'area';
   391→
   392→    return {
   393→      type: chartType,
   394→      data: {
   395→        labels: this.data!.labels || [],
   396→        datasets: this.data!.datasets.map((dataset, dsIndex) => {
   397→          const hex = modernPalette[dsIndex % modernPalette.length];
   398→          const { r, g, b } = this.hexToRgb(hex);
   399→
   400→          // Gradient fill under the line
   401→          const fillGradient = ctx.createLinearGradient(0, 0, 0, ctx.canvas.height);
   402→          fillGradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${isArea ? 0.35 : 0.15})`);
   403→          fillGradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0.01)`);
   404→
   405→          return {
