   515→          const value = chart.data.datasets[0].data[idx];
   516→          if (value == null || value === 0) return;
   517→
   518→          const pct = ((value / total) * 100).toFixed(1);
   519→          // Position label at midpoint of the arc
   520→          const { x, y } = arc.tooltipPosition();
   521→
   522→          drawCtx.save();
   523→          drawCtx.font = "bold 13px 'Inter', sans-serif";
   524→          drawCtx.fillStyle = '#ffffff';
   525→          drawCtx.textAlign = 'center';
