   594→  /**
   595→   * Create a vertical gradient for a bar from a base color
   596→   */
   597→  private createBarGradient(ctx: CanvasRenderingContext2D, hex: string): CanvasGradient {
   598→    const gradient = ctx.createLinearGradient(0, 0, 0, ctx.canvas.height);
   599→    const { r, g, b } = this.hexToRgb(hex);
   600→    gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0.9)`);
   601→    gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0.4)`);
   602→    return gradient;
   603→  }
   604→
   605→  private createHorizontalBarGradient(ctx: CanvasRenderingContext2D, hex: string): CanvasGradient {
   606→    const gradient = ctx.createLinearGradient(0, 0, ctx.canvas.width, 0);
   607→    const { r, g, b } = this.hexToRgb(hex);
   608→    gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0.4)`);
   609→    gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0.9)`);
   610→    return gradient;
   611→  }
   612→
   613→  /**
   614→   * Format large numbers compactly: 44500000 → "$44.5M"
   615→   */
   616→  private formatCompactValue(value: number): string {
   617→    const prefix = this.valuePrefix;
   618→    const suffix = this.valueSuffix;
   619→    const abs = Math.abs(value);
   620→    const sign = value < 0 ? '-' : '';
   621→    let compact: string;
   622→    if (abs >= 1_000_000_000) compact = `${(abs / 1_000_000_000).toFixed(1)}B`;
   623→    else if (abs >= 1_000_000) compact = `${(abs / 1_000_000).toFixed(1)}M`;
   624→    else if (abs >= 1_000) compact = `${(abs / 1_000).toFixed(1)}K`;
   625→    else compact = `${abs}`;
   626→    return `${sign}${prefix}${compact}${suffix}`;
   627→  }
   628→
   629→  private hexToRgb(hex: string): { r: number; g: number; b: number } {
   630→    const r = parseInt(hex.slice(1, 3), 16);
   631→    const g = parseInt(hex.slice(3, 5), 16);
   632→    const b = parseInt(hex.slice(5, 7), 16);
   633→    return { r, g, b };
   634→  }
