   649→  private mapToChartJsType(type: ChartType): ChartJsType {
   650→    const typeMap: Partial<Record<ChartType, ChartJsType>> = {
   651→      bar: 'bar',
   652→      line: 'line',
   653→      pie: 'pie',
   654→      scatter: 'scatter',
   655→      radar: 'radar',
   656→      doughnut: 'doughnut',
   657→      area: 'line',
   658→      horizontalBar: 'bar',
   659→      stackedBar: 'bar',
   660→      stackedArea: 'line',
   661→    };
   662→    return typeMap[type] || 'bar';
