   668→  private buildScales(chartType: ChartJsType): any {
   669→    // Pie, doughnut, and radar charts don't use standard x/y scales
   670→    if (['pie', 'doughnut', 'radar'].includes(chartType)) {
   671→      return undefined;
   672→    }
   673→
   674→    return {
   675→      x: {
   676→        title: {
   677→          display: !!this.xLabel,
   678→          text: this.xLabel || '',
   679→        },
   680→      },
   681→      y: {
   682→        title: {
   683→          display: !!this.yLabel,
   684→          text: this.yLabel || '',
   685→        },
   686→        beginAtZero: true,
   687→      },
   688→    };
   689→  }
