   691→  /**
   692→   * Get colorblind-safe colors from Tailwind palette
   693→   */
   694→  private getColors(index: number, _total: number, alpha: number): string {
   695→    const palettes = {
   696→      default: ['#3b82f6', '#06b6d4', '#f97316', '#8b5cf6', '#ec4899', '#f59e0b'],
   697→      sequential: ['#dbeafe', '#93c5fd', '#3b82f6', '#1e40af', '#1e3a8a'],
   698→      diverging: ['#ef4444', '#f97316', '#fbbf24', '#a3e635', '#22c55e'],
   699→      status: ['#22c55e', '#fbbf24', '#ef4444'],
   700→      categorical: ['#3b82f6', '#ec4899', '#f59e0b', '#8b5cf6', '#06b6d4', '#f97316'],
   701→    };
   702→
   703→    const palette = palettes[this.colorScheme || 'default'];
   704→    const color = palette[index % palette.length];
   705→
   706→    // Convert hex to rgba with alpha
   707→    const r = parseInt(color.slice(1, 3), 16);
   708→    const g = parseInt(color.slice(3, 5), 16);
   709→    const b = parseInt(color.slice(5, 7), 16);
   710→
   711→    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
   712→  }
   713→
   714→  /**
   715→   * Handle chart click for drill-downs
   716→   */
   717→  private handleChartClick(_event: any, elements: any[]): void {
   718→    console.log('Chart clicked!', { interactive: this.interactive, elementsLength: elements.length });
   719→
   720→    if (!this.interactive || elements.length === 0) {
   721→      console.log('Click ignored - interactive:', this.interactive, 'elements:', elements.length);
   722→      return;
   723→    }
   724→
   725→    const element = elements[0];
   726→    const datasetIndex = element.datasetIndex;
   727→    const dataIndex = element.index;
   728→
   729→    const dataset = this.data?.datasets[datasetIndex];
   730→    const label = this.data?.labels?.[dataIndex];
   731→    const value = dataset?.data[dataIndex];
   732→
   733→    console.log('Emitting drill-down action:', { label, value, datasetLabel: dataset?.label });
   734→
   735→    if (label !== undefined && value !== undefined) {
   736→      // Send drill-down action via A2UI
   737→      // Action interface requires 'name' and context as array of key-value pairs
   738→      this.sendAction({
   739→        name: 'drill_down',
   740→        context: [
   741→          { key: 'label', value: { literalString: String(label) } },
   742→          { key: 'value', value: { literalNumber: value as number } },
   743→          { key: 'datasetLabel', value: { literalString: dataset?.label || '' } },
   744→        ],
   745→      } as any);
   746→    }
