     9→/**
    10→ * AutoScrollDirective
    11→ *
    12→ * Automatically scrolls an element to the bottom when content changes,
    13→ * but only if the user hasn't manually scrolled up.
    14→ *
    15→ * Usage: <div appAutoScroll>...</div>
    16→ */
    17→@Directive({
    18→  selector: '[appAutoScroll]',
    19→  standalone: true,
    20→})
    21→export class AutoScrollDirective implements AfterViewChecked, OnDestroy {
    22→  @Input() autoScrollEnabled = true;
    23→
    24→  private isNearBottom = true;
    25→  private mutationObserver?: MutationObserver;
    26→
    27→  constructor(private elementRef: ElementRef<HTMLElement>) {
    28→    this.setupScrollListener();
    29→    this.setupMutationObserver();
    30→  }
    31→
    32→  ngAfterViewChecked(): void {
    33→    if (this.autoScrollEnabled && this.isNearBottom) {
    34→      this.scrollToBottom();
    35→    }
    36→  }
    37→
    38→  ngOnDestroy(): void {
    39→    this.mutationObserver?.disconnect();
    40→  }
    41→
    42→  /**
    43→   * Listen for scroll events to track if user has scrolled up
    44→   */
    45→  private setupScrollListener(): void {
    46→    const element = this.elementRef.nativeElement;
    47→
    48→    element.addEventListener('scroll', () => {
    49→      const scrollTop = element.scrollTop;
    50→      const scrollHeight = element.scrollHeight;
    51→      const clientHeight = element.clientHeight;
    52→
    53→      // Consider "near bottom" if within 100px of bottom
    54→      const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
    55→      this.isNearBottom = distanceFromBottom < 100;
    56→    });
    57→  }
    58→
    59→  /**
    60→   * Watch for DOM mutations to trigger scroll
    61→   */
    62→  private setupMutationObserver(): void {
    63→    const element = this.elementRef.nativeElement;
    64→
    65→    this.mutationObserver = new MutationObserver(() => {
    66→      if (this.isNearBottom) {
    67→        this.scrollToBottom();
    68→      }
    69→    });
    70→
    71→    this.mutationObserver.observe(element, {
    72→      childList: true,
    73→      subtree: true,
    74→    });
    75→  }
    76→
    77→  /**
    78→   * Scroll the element to the bottom
    79→   */
    80→  private scrollToBottom(): void {
    81→    const element = this.elementRef.nativeElement;
    82→    element.scrollTop = element.scrollHeight;
    83→  }
    84→}
